  "content": "1|import { STUDIO_PORTAL_SEGMENT } from '../../../../shared/api/contracts/platform/mountConstants';
2|import { buildDesignerComponentPath } from '../../../../shared/lib/designerComponentPath';
3|import type { DataSourceDefinition } from '../../../../domain/component-designer/types';
4|import { coerceBindingDefinitions } from '../../../../domain/component-designer/bindingRegistry';
5|import type { NativeToolDefinition } from '../ToolRegistry';
6|import { executeDraftComponentLayout } from './draftComponentLayout';
7|import {
8|  getAgentDraft,
9|  putAgentDraft,
10|  type ComponentLayoutDraft,
11|  type ComponentLayoutMenuEntry,
12|} from './agentDraftStore';
13|
14|export const DRAFT_APPLICATION_SCAFFOLD_TOOL_NAME = 'draft_application_scaffold';
15|
16|const isRecord = (value: unknown): value is Record<string, unknown> => (
17|  Boolean(value) && typeof value === 'object' && !Array.isArray(value)
18|);
19|
20|const slugifyName = (name: string): string => (
21|  name.trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'untitled-app'
22|);
23|
24|type ScaffoldPageInput = {
25|  name: string;
26|  templateId?: string;
27|  description?: string;
28|  /** Defaults to true — mirrors DesignerAddToMenuButton for each page. */
29|  addToMenu?: boolean;
30|};
31|
32|const parsePages = (value: unknown): ScaffoldPageInput[] | { error: string } => {
33|  if (!Array.isArray(value) || value.length === 0) {
34|    return { error: 'pages must be a non-empty array of { name, templateId?, description?, addToMenu? }.' };
35|  }
36|
37|  const pages: ScaffoldPageInput[] = [];
38|  for (const entry of value) {
39|    if (!isRecord(entry)) {
40|      return { error: 'Each page must be an object with a name.' };
41|    }
42|    const name = typeof entry.name === 'string' ? entry.name.trim() : '';
43|    if (!name) {
44|      return { error: 'Each page requires a non-empty name.' };
45|    }
46|    pages.push({
47|      name,
48|      templateId: typeof entry.templateId === 'string' ? entry.templateId.trim() : undefined,
49|      description: typeof entry.description === 'string' ? entry.description.trim() : undefined,
50|      addToMenu: entry.addToMenu === false ? false : true,
51|    });
52|  }
53|  return pages;
54|};
55|
56|const parseSharedDataSources = (value: unknown): Record<string, DataSourceDefinition> => {
57|  if (!isRecord(value)) return {};
58|  const next: Record<string, DataSourceDefinition> = {};
59|  for (const [key, entry] of Object.entries(value)) {
60|    if (!key.trim() || !isRecord(entry)) continue;
61|    next[key.trim()] = entry as DataSourceDefinition;
62|  }
63|  return next;
64|};
65|
66|const mergeSharedDataSourcesIntoDraft = (
67|  draft: ComponentLayoutDraft,
68|  sharedDataSources: Record<string, DataSourceDefinition>,
69|): ComponentLayoutDraft => {
70|  if (Object.keys(sharedDataSources).length === 0) return draft;
71|
72|  const registry = coerceBindingDefinitions(draft.bindingDefinitions);
73|  const merged = {
74|    ...registry,
75|    dataSources: {
76|      ...registry.dataSources,
77|      ...sharedDataSources,
78|    },
79|  };
80|
81|  const updated: ComponentLayoutDraft = {
82|    ...draft,
83|    bindingDefinitions: merged as unknown as ComponentLayoutDraft['bindingDefinitions'],
84|  };
85|  putAgentDraft(updated);
86|  return updated;
87|};
88|
89|const attachMenuEntry = (
90|  draft: ComponentLayoutDraft,
91|  portalSegment: string,
92|): ComponentLayoutDraft => {
93|  const componentPath = buildDesignerComponentPath(draft.folder, draft.name);
94|  const menuEntry: ComponentLayoutMenuEntry = {
95|    portalSegment,
96|    navLabel: draft.name,
97|    pageKey: componentPath,
98|    path: `${componentPath}/`,
99|    loaderRef: componentPath,
100|  };
101|  const updated: ComponentLayoutDraft = { ...draft, menuEntry };
102|  putAgentDraft(updated);
103|  return updated;
104|};
105|
106|/**
107| * Orchestrates multiple `draft_component_layout` calls (pages + shell) and attaches
108| * portal menu intents — no parallel document generator.
109| */
110|export const executeDraftApplicationScaffold = async (args: Record<string, unknown>) => {
111|  const appName = typeof args.appName === 'string' ? args.appName.trim() : '';
112|  if (!appName) {
113|    return { ok: false as const, summary: 'Application name is required.', error: 'missing_app_name' };
114|  }
115|
116|  const pagesResult = parsePages(args.pages);
117|  if ('error' in pagesResult) {
118|    return { ok: false as const, summary: pagesResult.error, error: 'invalid_pages' };
119|  }
120|
121|  const folder = typeof args.folder === 'string' && args.folder.trim()
122|    ? args.folder.trim().toLowerCase()
123|    : slugifyName(appName);
124|  const shellTemplateId = typeof args.shellTemplateId === 'string' && args.shellTemplateId.trim()
125|    ? args.shellTemplateId.trim()
126|    : 'app-shell';
127|  const portalSegment = typeof args.portalSegment === 'string' && args.portalSegment.trim()
128|    ? args.portalSegment.trim()
129|    : STUDIO_PORTAL_SEGMENT;
130|  const description = typeof args.description === 'string' ? args.description.trim() : undefined;
131|  const sharedDataSources = parseSharedDataSources(args.sharedDataSources);
132|
133|  const shellResult = await executeDraftComponentLayout({
134|    name: `${appName} Shell`,
135|    folder,
136|    templateId: shellTemplateId,
137|    description: description
138|      ? `Shell for ${appName}: ${description}`
139|      : `Application shell for ${appName}`,
140|  });"
}
